-- Approved weighing evidence replaces Workify chip estimates during the covered year.
alter table private.hub_saw_activity_rules_v1 add column chip_weigh_from date,add column chip_weigh_to date;
create table private.hub_saw_chip_deliveries_v1 (
 tenant_id uuid not null, unit_id uuid not null references public.hub_objects(id),
 ticket_number text not null, occurred_on date not null, tons numeric not null check(tons>0),
 order_numbers text[] not null, customer text, evidence text, source_file text not null, source_page integer not null,
 primary key(tenant_id,ticket_number));
alter table private.hub_saw_chip_deliveries_v1 enable row level security;
revoke all on private.hub_saw_chip_deliveries_v1 from public,anon,authenticated;
comment on table private.hub_saw_chip_deliveries_v1 is 'User-approved saw chip evidence. Source order references are audit evidence, not canonical identities. Unique weighing ticket prevents repeated credit.';
